insert into public."Location"("id (PK)","name_modern","name_ancient","description","address","categories","historical_story","poetry_literature","historical_event","related_literature","heritage_grade","period","literature_source","research_notes","coordinate_system","coordinate_status","coordinate_note","catalog_key","source_document","source_section","related_figures","data_status",coordinates,themes,photos,is_core_site,route_eligible,"Topic",is_ar_enabled) values (96,'石屋洞题名','石屋洞','苏轼与陈襄、苏颂、孙奕、黄颢、曾孝章同游石屋洞题名','西湖区南高峰下石屋洞','峰峦岩洞','苏轼与陈襄、苏颂、孙奕、黄颢、曾孝章同游石屋洞题名','题名原文：“陈襄、苏颂、孙奕、黄颢、曾孝章、苏轼同游，熙宁六年二月二十一日。”','苏轼与陈襄、苏颂、孙奕、黄颢、曾孝章同游石屋洞题名','题名原文：“陈襄、苏颂、孙奕、黄颢、曾孝章、苏轼同游，熙宁六年二月二十一日。”','确证','熙宁六年（1073）二月二十一日','《冷庐杂识》；《两浙金石志》','石屋洞内北壁东侧存此题名，共25字。目前发现苏轼留在杭州最早的摩崖题刻，记录了熙宁六年二月与知州陈襄等同游事。题名字画完好，但相传党禁时曾被镌去。','GCJ-02','point','定位参考：石屋洞；https://www.openstreetmap.org/node/13325549759。OSM/Photon WGS-84 转 GCJ-02，2026-10-14 核对。为现代景点参考位置，现场入口及历史题刻位置请再核验。','dongpo-hangzhou-20','附录B 苏轼杭州行迹考订清单','西湖周边行迹','[4]','documented',ARRAY[120.130467,30.219406]::double precision[],ARRAY['交游酬唱','诗词题咏','自然景观']::text[],'[]'::jsonb,false,true,'苏轼·杭州行迹',false);
