insert into public."Location"("id (PK)","name_modern","name_ancient","description","address","categories","historical_story","poetry_literature","historical_event","related_literature","heritage_grade","period","literature_source","research_notes","coordinate_system","coordinate_status","coordinate_note","catalog_key","source_document","source_section","related_figures","data_status",coordinates,themes,photos,is_core_site,route_eligible,"Topic",is_ar_enabled) values (97,'水乐洞','水乐洞','苏轼到访水乐洞，作《水乐洞小记》','西湖区满觉陇山腰（烟霞三洞之一）','泉池溪涧','苏轼到访水乐洞，作《水乐洞小记》','《水乐洞小记》（“钱塘东南有水乐洞，泉流岩中，皆自然宫商”）','苏轼到访水乐洞，作《水乐洞小记》','《水乐洞小记》（“钱塘东南有水乐洞，泉流岩中，皆自然宫商”）','确证','熙宁四年至五年（1071—1072）','《西湖游览志》；《咸淳临安志》','水乐洞在烟霞岭下，熙宁二年郡守郑獬命名，后二年苏轼来为倅遂赋诗。今为杭州市级文保单位，洞内外有摩崖石刻。','GCJ-02','point','定位参考：水乐洞；https://www.openstreetmap.org/node/5604066549。OSM/Photon WGS-84 转 GCJ-02，2026-10-14 核对。为现代景点参考位置，现场入口及历史题刻位置请再核验。','dongpo-hangzhou-21','附录B 苏轼杭州行迹考订清单','西湖周边行迹','[4]','documented',ARRAY[120.123328,30.218218]::double precision[],ARRAY['诗词题咏','自然景观']::text[],'[]'::jsonb,false,true,'苏轼·杭州行迹',false);
