insert into public."Location"("id (PK)","name_modern","name_ancient","description","address","categories","historical_story","poetry_literature","historical_event","related_literature","heritage_grade","period","literature_source","research_notes","coordinate_system","coordinate_status","coordinate_note","catalog_key","source_document","source_section","related_figures","data_status",coordinates,themes,photos,is_core_site,route_eligible,"Topic",is_ar_enabled) values (105,'於潜（青牛岭、绿筠轩）','於潜、青牛岭、绿筠轩','苏轼巡行属县至於潜“视政”，访僧问禅','临安区於潜镇一带','林野花谷','苏轼巡行属县至於潜“视政”，访僧问禅','《於潜僧绿筠轩》（“可使食无肉，不可居无竹”）、《青牛岭高绝处有小寺人迹罕到》','苏轼巡行属县至於潜“视政”，访僧问禅','《於潜僧绿筠轩》（“可使食无肉，不可居无竹”）、《青牛岭高绝处有小寺人迹罕到》','确证','熙宁六年（1073）春、熙宁七年（1074）六月至九月','《苏轼诗集》卷九、卷十二','熙宁六年春，苏轼去富阳、新城“视政”后紧接着去了於潜“视政”。熙宁七年六月至九月苏轼仍在杭州、於潜一带活动。於潜僧绿筠轩旧址今在临安区於潜镇。','GCJ-02','area','定位参考：於潜；https://www.openstreetmap.org/node/1750036268。OSM/Photon WGS-84 转 GCJ-02，2026-10-14 核对。为区域参考点，不代表历史遗址的精确位置。','dongpo-hangzhou-29','附录B 苏轼杭州行迹考订清单','属县行迹','[4]','documented',ARRAY[119.400379,30.177608]::double precision[],ARRAY['民生善政','交游酬唱','诗词题咏','自然景观']::text[],'[]'::jsonb,false,false,'苏轼·杭州行迹',false);
