update public."Location" set "name_modern"='大麦岭摩崖题刻',"name_ancient"='大麦岭',"description"='苏轼与王瑜、杨杰、张璹同游天竺，过麦岭并题名',"address"='西湖区三台山下大麦岭东麓',"categories"='峰峦岩洞',"historical_story"='苏轼与王瑜、杨杰、张璹同游天竺，过麦岭并题名',"poetry_literature"='题名原文：“苏轼、王瑜、杨杰、张璹同游天竺，过麦岭。”',"historical_event"='苏轼与王瑜、杨杰、张璹同游天竺，过麦岭并题名',"related_literature"='题名原文：“苏轼、王瑜、杨杰、张璹同游天竺，过麦岭。”',"heritage_grade"='确证',"period"='元祐五年（1090）三月',"literature_source"='《两浙金石志》卷六；《咸淳临安志》',"research_notes"='摩崖石刻高1.4米，长1.8米，字径约10厘米，阴刻楷书，文右行。杭州现存唯一可信的苏轼题记原物，未经党禁磨砻。同游三人与龙华寺题名、韬光题名同，均为元祐五年三月二日所书，故不复纪年。因地处偏僻得以存留至今。',"coordinate_system"='GCJ-02',"coordinate_status"='area',"coordinate_note"='定位参考：大麦岭；https://www.openstreetmap.org/node/12730744387。OSM/Photon WGS-84 转 GCJ-02，2026-10-14 核对。为区域参考点，不代表历史遗址的精确位置。',"catalog_key"='dongpo-hangzhou-19',"source_document"='附录B 苏轼杭州行迹考订清单',"source_section"='西湖周边行迹',"related_figures"='[4]',"data_status"='documented',coordinates=ARRAY[120.128638,30.232996]::double precision[],themes=ARRAY['交游酬唱','诗词题咏','自然景观']::text[],photos='[{"url": "https://msjzwtigdinhdygpmnuh.supabase.co/storage/v1/object/public/dongpo-site-images/catalog/07/18831b22f3a7ebed00a0.jpg", "caption": "大麦岭摩崖题刻_01_全景", "credit": "杭州市园林文物局", "source": "https://z.hangzhou.com.cn/2021/syjy/content/content_8176987.html", "license": "用户确认已获 APP 展示授权（2026-10-14）", "kind": "网络参考图", "original_file": "07_大麦岭摩崖题刻_01_全景.jpg", "original_sha256": "18831b22f3a7ebed00a05a74bb9ab6aa0de106038f15cb69a5d076b0b79e4c86", "original_size": "550×371", "storage_path": "catalog/07/18831b22f3a7ebed00a0.jpg", "asset_path": "assets/images/dongpo/18831b22f3a7ebed00a0.jpg"}, {"url": "https://msjzwtigdinhdygpmnuh.supabase.co/storage/v1/object/public/dongpo-site-images/catalog/07/0bd7eea8c3e048ed0fa3.jpg", "caption": "大麦岭摩崖题刻_02_麦岭题刻", "credit": "杭州市园林文物局", "source": "https://z.hangzhou.com.cn/2021/syjy/content/content_8176987.html", "license": "用户确认已获 APP 展示授权（2026-10-14）", "kind": "网络参考图", "original_file": "07_大麦岭摩崖题刻_02_麦岭题刻.jpg", "original_sha256": "0bd7eea8c3e0